<section class="columns is-centered"><div class="column is-half-tablet is-one-third-widescreen"><div class="box"><h1 class="title is-3">Verify your email</h1><p class="mb-4">Enter the one-time token sent to your inbox. It expires after 30 minutes.</p><div id="verification-message" class="notification is-hidden" role="status" aria-live="polite"></div>
<form id="verify-form"><div class="field"><label class="label" for="email">Email</label><input class="input" id="email" type="email" maxlength="254" autocomplete="email" required></div><div class="field"><label class="label" for="token">Verification token</label><input class="input" id="token" maxlength="128" autocomplete="one-time-code" required></div><button class="button is-primary is-fullwidth" type="submit">Verify email</button></form>
<hr><form id="resend-form"><input type="hidden" id="resend-email"><button class="button is-light is-fullwidth" type="submit">Resend verification email</button></form><p class="help mt-2">Resend replies do not reveal whether an account exists.</p><p class="mt-4"><a href="{{ route('login') }}">Back to sign in</a></p></div></div></section>
<script nonce="{{ request()->attributes->get('csp_nonce') }}">
(() => {const email=document.getElementById('email'),token=document.getElementById('token'),message=document.getElementById('verification-message'),verify=document.getElementById('verify-form'),resend=document.getElementById('resend-form');try{email.value=sessionStorage.getItem('verificationEmail')||'';}catch{}document.getElementById('resend-email').value=email.value;email.addEventListener('input',()=>document.getElementById('resend-email').value=email.value);const submit=async(url,payload,success)=>{message.className='notification is-info';message.textContent='Submitting…';try{const response=await fetch(url,{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.message||Object.values(result.errors||{}).flat().join(' ')||'Request failed.');message.className='notification is-success';message.textContent=success(result);}catch(error){message.className='notification is-danger';message.textContent=error.message||'Unable to contact the server.';}};verify.addEventListener('submit',event=>{event.preventDefault();submit('/api/v1/auth/email/verify',{email:email.value,token:token.value},()=>{verify.hidden=true;resend.hidden=true;return 'Email verified. You can now sign in.';});});resend.addEventListener('submit',event=>{event.preventDefault();document.getElementById('resend-email').value=email.value;submit('/api/v1/auth/email/resend',{email:email.value},result=>result.message);});})();
</script>
